import React from 'react';

interface ShippingOption {
  service: string;
  cents: number;
  etaDays: number;
}

interface ShippingSelectorProps {
  options: ShippingOption[];
  onChange: (option: ShippingOption) => void;
}

const formatCents = (cents: number): string => {
  return `$${(cents / 100).toFixed(2)}`;
};

const ShippingSelector: React.FC<ShippingSelectorProps> = ({ options, onChange }) => {
  const [selectedOption, setSelectedOption] = React.useState<ShippingOption | null>(null);

  const handleOptionChange = (option: ShippingOption) => {
    setSelectedOption(option);
    onChange(option);
  };

  return (
    <div className="mt-4">
      <div className="text-sm font-medium text-gray-700 mb-2">Shipping Options</div>
      <div className="space-y-2">
        {options.map((option, index) => (
          <div
            key={index}
            className="flex items-center border rounded-md p-3 cursor-pointer hover:bg-gray-50"
            onClick={() => handleOptionChange(option)}
          >
            <input
              type="radio"
              id={`shipping-option-${index}`}
              name="shipping-option"
              checked={selectedOption?.service === option.service}
              onChange={() => handleOptionChange(option)}
              className="h-4 w-4 text-blue-600 focus:ring-blue-500 border-gray-300"
            />
            <div className="ml-3">
              <label
                htmlFor={`shipping-option-${index}`}
                className="block text-sm font-medium text-gray-900"
              >
                {option.service}
              </label>
              <div className="text-sm text-gray-500">
                {formatCents(option.cents)} | {option.etaDays} day{option.etaDays !== 1 ? 's' : ''}
              </div>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

export default ShippingSelector;

import logging
import logging.config
import yaml
import os

def setup_logging(settings: dict):
    """
    Configure logging using the provided settings dictionary.
    """
    if 'LOG_LEVEL' not in settings:
        raise ValueError("LOG_LEVEL must be specified in settings")

    if 'LOG_FORMAT' not in settings:
        settings['LOG_FORMAT'] = '%(asctime)s %(levelname)s %(name)s %(message)s'

    log_config = {
        'version': 1,
        'disable_existing_loggers': False,
        'formatters': {
            'default': {
                'format': settings['LOG_FORMAT'],
                'datefmt': '%Y-%m-%d %H:%M:%S',
            },
        },
        'handlers': {
            'console': {
                'class': 'logging.StreamHandler',
                'formatter': 'default',
                'stream': 'ext://sys.stdout',
            },
        },
        'root': {
            'level': settings['LOG_LEVEL'],
            'handlers': ['console'],
        },
    }

    logging.config.dictConfig(log_config)

def load_settings():
    """
    Load settings from config/settings.yaml.
    """
    config_path = os.path.join(os.path.dirname(__file__), '..', 'config', 'settings.yaml')
    if not os.path.exists(config_path):
        raise FileNotFoundError(f"Settings file not found at {config_path}")

    with open(config_path, 'r') as f:
        return yaml.safe_load(f)

def configure_logging():
    """
    Load settings and configure logging.
    """
    settings = load_settings()
    setup_logging(settings)

